<?php
/**
 * Theme functions.
 *
 * @package my-theme
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/*
 * Self-hosted fonts, generated by scripts/fetch-fonts.mjs into assets/fonts/.
 * Loading them from fonts.googleapis.com would send every visitor's IP address
 * to Google — a consent question under GDPR. Local files raise none.
 */
const MY_THEME_FONTS = 'assets/fonts/fonts.css';

add_action(
	'after_setup_theme',
	function () {
		add_theme_support( 'wp-block-styles' );
		add_theme_support( 'responsive-embeds' );
		add_theme_support( 'editor-styles' );
		// The editor composes in the real typeface, and editor.css repairs what the
		// Gutenberg canvas breaks (position: relative forced on every block).
		// Acceptance gate 5 checks it.
		add_editor_style( array( MY_THEME_FONTS, 'style.css', 'assets/editor.css' ) );
	}
);

add_action(
	'wp_enqueue_scripts',
	function () {
		$version = wp_get_theme()->get( 'Version' );
		$deps    = array();

		if ( file_exists( get_theme_file_path( MY_THEME_FONTS ) ) ) {
			wp_enqueue_style( 'my-theme-fonts', get_theme_file_uri( MY_THEME_FONTS ), array(), $version );
			$deps[] = 'my-theme-fonts';
		}

		wp_enqueue_style( 'my-theme', get_stylesheet_uri(), $deps, $version );

		// Never enqueue a missing file: that is a 404 on every page.
		if ( file_exists( get_theme_file_path( 'assets/app.js' ) ) ) {
			wp_enqueue_script( 'my-theme', get_theme_file_uri( 'assets/app.js' ), array(), $version, array( 'strategy' => 'defer' ) );
		}
	}
);

add_action(
	'init',
	function () {
		register_block_pattern_category( 'my-theme', array( 'label' => __( 'My Theme', 'my-theme' ) ) );
	}
);

/*
 * The Shortcode block runs wpautop() on its content: a form shortcode comes out
 * wrapped in a <p> that the browser splits into empty paragraphs around the
 * form, which breaks grid layouts. Run the raw shortcode instead. This also
 * makes shortcodes work inside template parts.
 */
add_filter(
	'render_block_core/shortcode',
	function ( $html, $block ) {
		return do_shortcode( trim( $block['innerHTML'] ?? $html ) );
	},
	10,
	2
);
